// A social network a channel connects to.
type Platform string

const (
	PlatformX              Platform = "x"
	PlatformLinkedin       Platform = "linkedin"
	PlatformBluesky        Platform = "bluesky"
	PlatformMastodon       Platform = "mastodon"
	PlatformThreads        Platform = "threads"
	PlatformInstagram      Platform = "instagram"
	PlatformFacebook       Platform = "facebook"
	PlatformTiktok         Platform = "tiktok"
	PlatformYoutube        Platform = "youtube"
	PlatformPinterest      Platform = "pinterest"
	PlatformGoogleBusiness Platform = "googleBusiness"
	PlatformDiscord        Platform = "discord"
	PlatformTelegram       Platform = "telegram"
	PlatformSlack          Platform = "slack"
)

func NewPlatformFromString(s string) (Platform, error) {
	switch s {
	case "x":
		return PlatformX, nil
	case "linkedin":
		return PlatformLinkedin, nil
	case "bluesky":
		return PlatformBluesky, nil
	case "mastodon":
		return PlatformMastodon, nil
	case "threads":
		return PlatformThreads, nil
	case "instagram":
		return PlatformInstagram, nil
	case "facebook":
		return PlatformFacebook, nil
	case "tiktok":
		return PlatformTiktok, nil
	case "youtube":
		return PlatformYoutube, nil
	case "pinterest":
		return PlatformPinterest, nil
	case "googleBusiness":
		return PlatformGoogleBusiness, nil
	case "discord":
		return PlatformDiscord, nil
	case "telegram":
		return PlatformTelegram, nil
	case "slack":
		return PlatformSlack, nil
	}
	var t Platform
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (p Platform) Ptr() *Platform {
	return &p
}

